(function(window,document){'use strict';function prefersReducedMotion(){return window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;}
function animateCounters(root){var els=(root||document).querySelectorAll('[data-animate-counter]');if(!els.length||prefersReducedMotion())return;els.forEach(function(el){if(el.__acCounterDone)return;el.__acCounterDone=true;var text=el.textContent;var match=text.match(/-?\d+(\.\d+)?/);if(!match)return;var target=parseFloat(match[0]);var decimals=(match[0].split('.')[1]||'').length;var prefix=text.slice(0,match.index);var suffix=text.slice(match.index+match[0].length);var duration=parseInt(el.getAttribute('data-duration'),10)||900;var start=null;function frame(ts){if(start===null)start=ts;var progress=Math.min(1,(ts-start)/duration);var eased=1-Math.pow(1-progress,3);el.textContent=prefix+(target*eased).toFixed(decimals)+suffix;if(progress<1){requestAnimationFrame(frame);}else{el.textContent=prefix+target.toFixed(decimals)+suffix;}}
requestAnimationFrame(frame);});}
var SCRAMBLE_CHARS='ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';function scrambleText(el,opts){if(prefersReducedMotion())return;opts=opts||{};var finalText=el.getAttribute('data-scramble-text')||el.textContent;var duration=opts.duration||700;var frameDelay=opts.frameDelay||35;var frame=0;var totalFrames=Math.round(duration/frameDelay);function render(){var progress=frame/totalFrames;var revealCount=Math.floor(progress*finalText.length);var out='';for(var i=0;i<finalText.length;i++){var ch=finalText[i];out+=(i<revealCount||ch===' ')?ch:SCRAMBLE_CHARS[Math.floor(Math.random()*SCRAMBLE_CHARS.length)];}
el.textContent=out;frame++;if(frame<=totalFrames){setTimeout(render,frameDelay);}else{el.textContent=finalText;}}
render();}
function initScrambles(root){(root||document).querySelectorAll('[data-scramble]').forEach(function(el){if(el.__acScrambled)return;el.__acScrambled=true;scrambleText(el);});}
function initRipple(){document.addEventListener('click',function(e){if(prefersReducedMotion())return;var target=e.target.closest('[data-ripple], .sb-item');if(!target)return;var rect=target.getBoundingClientRect();var size=Math.max(rect.width,rect.height)*1.6;var ripple=document.createElement('span');ripple.className='ac-ripple';ripple.style.width=ripple.style.height=size+'px';ripple.style.left=(e.clientX-rect.left-size/2)+'px';ripple.style.top=(e.clientY-rect.top-size/2)+'px';if(window.getComputedStyle(target).position==='static'){target.style.position='relative';}
target.classList.add('ac-ripple-host');target.appendChild(ripple);ripple.addEventListener('animationend',function(){ripple.remove();});});}
function particleBurst(el,opts){if(prefersReducedMotion())return;opts=opts||{};var count=opts.count||14;var colors=opts.colors||['#38bdf8','#a78bfa','#fbbf24','#34d399','#f472b6'];var rect=el.getBoundingClientRect();var cx=rect.left+rect.width/2;var cy=rect.top+rect.height/2;for(var i=0;i<count;i++){var p=document.createElement('span');p.className='ac-particle';var angle=(Math.PI*2*i)/count+Math.random()*0.4;var distance=40+Math.random()*40;p.style.setProperty('--ac-dx',(Math.cos(angle)*distance)+'px');p.style.setProperty('--ac-dy',(Math.sin(angle)*distance)+'px');p.style.background=colors[i%colors.length];p.style.left=cx+'px';p.style.top=cy+'px';document.body.appendChild(p);p.addEventListener('animationend',function(){this.remove();});}}
function initTilt(root){var els=(root||document).querySelectorAll('[data-tilt]');if(!els.length||prefersReducedMotion())return;if(window.matchMedia&&window.matchMedia('(pointer: coarse)').matches)return;els.forEach(function(card){if(card.__acTiltBound)return;card.__acTiltBound=true;var maxDeg=parseFloat(card.getAttribute('data-tilt-max'))||6;card.classList.add('ac-tilt');card.addEventListener('mousemove',function(e){var rect=card.getBoundingClientRect();var px=(e.clientX-rect.left)/rect.width;var py=(e.clientY-rect.top)/rect.height;var rotateY=(px-0.5)*2*maxDeg;var rotateX=(0.5-py)*2*maxDeg;card.style.transform='perspective(600px) rotateX('+rotateX.toFixed(2)+'deg) rotateY('+rotateY.toFixed(2)+'deg) translateZ(0)';});card.addEventListener('mouseleave',function(){card.style.transform='';});});}
function showSkeleton(key){document.querySelectorAll('[data-skeleton-for="'+key+'"]').forEach(function(el){el.classList.remove('u-d-none');});document.querySelectorAll('[data-skeleton-target="'+key+'"]').forEach(function(el){el.classList.add('u-d-none');});}
function hideSkeleton(key){document.querySelectorAll('[data-skeleton-for="'+key+'"]').forEach(function(el){el.classList.add('u-d-none');});document.querySelectorAll('[data-skeleton-target="'+key+'"]').forEach(function(el){el.classList.remove('u-d-none');});}
function init(root){animateCounters(root);initScrambles(root);initTilt(root);}
initRipple();document.addEventListener('DOMContentLoaded',function(){init(document);});window.AnimateCore={init:init,animateCounters:animateCounters,scrambleText:scrambleText,particleBurst:particleBurst,showSkeleton:showSkeleton,hideSkeleton:hideSkeleton,};})(window,document);